# owner: platform
"""Weekly timesheet rows, one line of text per worker."""

from typing import List

from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from hourglass.errors import ProjectError
from collections import Counter


def _validate(shifts: List[Shift]) -> None:
    if not shifts:
        raise ProjectError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("shift has no worker")


def _line(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"


def _busiest_first(minutes: dict) -> List[str]:
    def rank(name):
        return (-minutes[name], name)
    return sorted(minutes, key=rank)


def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest (most hours) first."""
    _validate(shifts)
    minutes = worker_minutes(shifts)
    counts = Counter(shift.worker for shift in shifts)
    order = _busiest_first(minutes)
    return [_line(name, counts[name], minutes[name])
            for name in order]
